def save_chunks_to_json(chunks, output_dir="data"):
    Path(output_dir).mkdir(parents=True, exist_ok=True)

    file_chunks = {}
    for chunk in chunks:
        file_chunks.setdefault(chunk["file"], []).append(chunk)

    for filename, chunk_list in file_chunks.items():
        output_path = os.path.join(output_dir, f"{filename}.parsed.json")
        with open(output_path, "w", encoding="utf-8") as f:
            json.dump(chunk_list, f, indent=2)

        logger.info(f"Saved {len(chunk_list)} chunks to {output_path}")

def _ensure_store_exists(path: str):
    # Create parent directory if needed and initialize file with []
    parent = os.path.dirname(path)
    if parent:
        os.makedirs(parent, exist_ok=True)
    if not os.path.exists(path):
        with open(path, "w", encoding="utf-8") as f:
            json.dump([], f, ensure_ascii=False, indent=2)

def _read_all(path: str):
    _ensure_store_exists(path)
    with open(path, "r", encoding="utf-8") as f:
        try:
            data = json.load(f)
            if isinstance(data, list):
                return data
        except json.JSONDecodeError:
            pass
    return []

def _atomic_write_list(path: str, data):
    dirpath = os.path.dirname(os.path.abspath(path)) or "."
    fd, tmp_path = tempfile.mkstemp(dir=dirpath, prefix="qa_tmp_", suffix=".json")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as tmpf:
            json.dump(data, tmpf, ensure_ascii=False, indent=2)
            tmpf.flush()
            os.fsync(tmpf.fileno())
        os.replace(tmp_path, path)
    finally:
        if os.path.exists(tmp_path):
            try:
                os.remove(tmp_path)
            except OSError:
                pass

